pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed parameter is the address to pass as newOwner
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: allow any address
        // Ensure msg.sender is the current owner (set in constructor to address(this) ), so we call directly

        // Try calling transferOwnership and record whether it reverted
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract enforces require(newOwner != address(0)), so when newOwner == address(0)
        // the call must revert (ok == false); for any newOwner != address(0) the call should succeed (ok == true)
        // This single assert encodes that rule and will pass on the reference for all inputs and fail on the mutant
        if (newOwner == address(0)) {
            assertTrue(!ok, "transferOwnership should revert when newOwner is zero");
        } else {
            assertTrue(ok, "transferOwnership should succeed when newOwner is non-zero");
        }
    }
}

