pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address nonOwner;

    function setUp() public {
        c = new C(address(this), address(this));
        // choose a non-owner address distinct from deployer (which is owner)
        nonOwner = address(0xBEEF);
        // ensure nonOwner is not the owner
        assert(c.owner() == address(this));
        assert(nonOwner != c.owner());
    }

    // Fuzz the newOwner value: for ALL newOwner addresses the reference must revert when caller is NOT the owner.
    function testFuzz_property(address newOwner) public {
        // Keep domain wide: allow any address including zero
        bool ok;

        // act as non-owner and attempt to call transferOwnership
        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: If caller is NOT the owner, transferOwnership must revert (ok == false) for ALL inputs.
        // Reference implementation enforces onlyOwner modifier; mutant might allow a non-owner call to succeed in some cases.
        assertTrue(!ok);
    }
}

