    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed parameter: newOwner (address) - must be able to hit address(0) among others
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no assume so fuzzer can try address(0)

        // Ensure msg.sender is the current owner (setUp assigned owner to address(this))
        // Call transferOwnership as the owner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: Reference contract guarantees that when the caller is owner,
        // transferOwnership(address(0)) must revert (so the call must not succeed)
