// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed params: an address newOwner and a boolean useProxy
    // The test deploys a helper Forwarder contract when useProxy is true which will call c.transferOwnership on behalf of the owner.
    // The owner (address(this) in setup) will be msg.sender for the call into c when called directly, and when called via Forwarder
    // the msg.sender seen by c will be the Forwarder contract address while tx.origin will still be the EOA executing the tx.
    // The reference contract checks only msg.sender==owner(), so an authorized actor that is the owner (EOA) calling directly or
    // a contract that has been allowed to act with msg.sender==owner via a low-level call (by using vm.prank to become owner) will behave accordingly.
    // The mutant additionally checks tx.origin==owner(), so when the call is relayed through a contract (tx.origin != owner), the mutant will revert while
    // the reference will not. We fuzz newOwner and useProxy to let the fuzzer find the failing scenario.
    function testFuzz_property(address newOwner, bool useProxy) public {
        // keep newOwner varied but avoid zero to make semantics clear
        if (newOwner == address(0)) newOwner = address(0xBEEF);

        // initial owner is address(this) because constructor _transferOwnership(_msgSender()) in Ownable
        address initialOwner = address(this);

        bool ok;

        if (!useProxy) {
            // direct call as the owner (msg.sender == owner, tx.origin == owner)
            // call should succeed on reference; mutant may also succeed in this case.
            // We call directly from this test contract (which is the owner) so msg.sender == owner.
            try c.transferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // deploy a forwarder contract that will call c.transferOwnership on behalf of the owner
            Forwarder f = new Forwarder(c);

            // we want the Forwarder to call c.transferOwnership as if the Forwarder is msg.sender (so msg.sender != tx.origin)
            // The EOA (this test) will execute the transaction that triggers the forwarder, thus tx.origin == address(this), but msg.sender seen by c will be the forwarder.
            // We must ensure the forwarder invokes c.transferOwnership in a call where msg.sender == address(f). The forwarder will do exactly that.

            try f.callTransferOwnership(newOwner) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // The universal property we assert: when calling transferOwnership via a contract proxy (useProxy == true), the reference contract
        // allows the owner to effect the transfer (call succeeds), but the mutant that checks tx.origin==owner will reject (call reverts) for some inputs.
        // We therefore assert that the call succeeded when performed through the forwarder (useProxy==true). This holds on the reference for all inputs,
        // but the mutant will fail for the proxy case because tx.origin != owner.
        // Note: We assert on c's behavior (whether transferOwnership call returned or reverted) via the ok flag.
        if (useProxy) {
            assertTrue(ok);
        } else {
            // when not proxying, both reference and mutant accept since msg.sender==tx.origin==owner here; we don't force a condition
            // but to keep the test deterministic in the single-assert requirement, assertTrue(true) is not allowed. So instead assert that the direct call also succeeded.
            assertTrue(ok);
        }
    }
}

// minimal helper that forwards a call to c.transferOwnership
contract Forwarder {
    C public c;
    constructor(C _c) { c = _c; }
    function callTransferOwnership(address newOwner) external {
        // this call will have msg.sender == address(this contract), and tx.origin == the EOA that invoked this function
        c.transferOwnership(newOwner);
    }
}
